<?php use App\Core\Csrf; $students=$students??[]; $categories=$categories??[]; $today=$today??date('Y-m-d'); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Invoice | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f6f7fb;color:#172033}.wrap{max-width:1000px;margin:30px auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px;margin-bottom:16px}.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}input,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ccd1db;border-radius:8px;margin:5px 0 12px}button,a{padding:10px 14px;border:0;border-radius:8px;background:#172033;color:#fff;text-decoration:none}.item{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px;align-items:end;border-top:1px solid #eee;padding-top:10px;margin-top:10px}@media(max-width:700px){.item{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="/finance">← Finance</a></p><h1>Create Invoice</h1><form method="post" action="/finance/invoices"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES) ?>"><section class="card"><div class="row"><label>Student<select name="student_id" required><option value="">Select student</option><?php foreach($students as $student): ?><option value="<?= (int)$student['id'] ?>"><?= htmlspecialchars($student['admission_no'].' — '.$student['first_name'].' '.$student['last_name']) ?></option><?php endforeach; ?></select></label><label>Invoice No.<input name="invoice_no" required placeholder="INV-2026-0001"></label><label>Invoice Date<input type="date" name="invoice_date" value="<?= htmlspecialchars($today) ?>" required></label><label>Due Date<input type="date" name="due_date"></label></div></section><section class="card"><h2>Items</h2><div id="items"><div class="item"><label>Description<input name="description[]" required></label><label>Qty<input type="number" step="0.01" min="0.01" name="quantity[]" value="1"></label><label>Unit amount<input type="number" step="0.01" min="0" name="unit_amount[]" required></label><label>Category<select name="category_id[]"><option value="">None</option><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>"><?= htmlspecialchars($category['name']) ?></option><?php endforeach; ?></select></label></div></div><button type="button" onclick="addItem()">+ Add item</button></section><section class="card"><label>Discount<input type="number" step="0.01" min="0" name="discount" value="0"></label><button type="submit">Issue invoice</button></section></form></main><script>function addItem(){const root=document.getElementById('items');const first=root.firstElementChild;const clone=first.cloneNode(true);clone.querySelectorAll('input').forEach((i,n)=>{i.value=n===0?'':(n===1?'1':'')});clone.querySelectorAll('select').forEach(s=>s.selectedIndex=0);root.appendChild(clone)}</script></body></html>
